    def test_get_pcie_check_non_dpu_device(self):
        p = Pcie('')
        p.dpu_pcie_devices = []
        p.confInfo = [
            {
                'id': '1f0b',
                'bus': '01',
                'dev': '00',
                'fn': '00'
            }
        ]
        p._device_id_to_bus_map = {'1f0b:00': '01'}
        p.check_pcie_sysfs = mock.MagicMock(return_value=True)
        info = p.get_pcie_check()
        assert len(info) == 1
        assert info[0]['result'] == 'Passed'

